import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Button, CircularProgress } from "@mui/material";
import { supabase } from "../supabase";

const VerifyPage = () => {
  const [status, setStatus] = useState("checking"); // checking | success | failed
  const [errorMsg, setErrorMsg] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const verifyUser = async () => {
      console.log("🔍 Starting verification...");
      console.log("🌐 Full URL:", window.location.href);
      console.log("🧵 sessionStorage keys:", Object.keys(sessionStorage));

      try {
        const { error } = await supabase.auth.exchangeCodeForSession();

        if (error) {
          console.error("❌ Session exchange error:", error.message);
          setErrorMsg("Session expired or invalid. Open the verification link in the same browser & tab where you signed up.");
          setStatus("failed");
          return;
        }

        console.log("✅ Session exchanged. Fetching user...");
        const { data: userData, error: userError } = await supabase.auth.getUser();

        if (userError) {
          console.error("❌ Failed to fetch user:", userError.message);
          setErrorMsg("Error fetching user info.");
          setStatus("failed");
          return;
        }

        const user = userData.user;
        if (!user?.email_confirmed_at) {
          console.warn("⚠️ Email not confirmed.");
          setErrorMsg("Your email is not verified yet.");
          setStatus("failed");
          return;
        }

        console.log("✅ Email confirmed:", user.email);

        const userId = user.id;
        const saved = JSON.parse(localStorage.getItem("signup_user"));

        if (saved) {
          const { name, dob, role } = saved;
          console.log("📦 Found profile data in localStorage:", saved);

          const { error: insertError } = await supabase.from("profiles").insert([
            { id: userId, name, dob, role },
          ]);

          if (insertError) {
            console.error("❌ Failed to insert profile:", insertError.message);
            setErrorMsg("Could not save your profile. Try logging in again.");
            setStatus("failed");
            return;
          }

          console.log("✅ Profile inserted into database.");
        } else {
          console.warn("⚠️ No profile data found in localStorage. Skipping insert.");
        }

        localStorage.removeItem("signup_user");
        console.log("🧹 Cleared signup_user from localStorage.");
        setStatus("success");

        setTimeout(() => {
          console.log("➡️ Redirecting to /dashboard...");
          navigate("/dashboard");
        }, 2000);
      } catch (err) {
        console.error("🔥 Unexpected error during verification:", err);
        setErrorMsg("Something went wrong. Please try again later.");
        setStatus("failed");
      }
    };

    verifyUser();
  }, [navigate]);

  return (
    <Box
      sx={{
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        textAlign: "center",
        px: 3,
      }}
    >
      {status === "checking" && (
        <>
          <CircularProgress sx={{ color: "#8E2839", mb: 2 }} />
          <Typography variant="h6" color="#8E2839">
            Verifying your account...
          </Typography>
        </>
      )}

      {status === "success" && (
        <>
          <Typography variant="h6" color="green" mb={1}>
            ✅ Verification successful!
          </Typography>
          <Typography>Redirecting to your dashboard...</Typography>
        </>
      )}

      {status === "failed" && (
        <>
          <Typography variant="h6" color="red" mb={1}>
            ❌ Verification failed
          </Typography>
          <Typography mb={2}>{errorMsg}</Typography>
          <Button
            variant="contained"
            sx={{ backgroundColor: "#8E2839" }}
            onClick={() => navigate("/signin")}
          >
            Back to Sign In
          </Button>
        </>
      )}
    </Box>
  );
};

export default VerifyPage;
